public static double averagePositiveDiff(int[] arr) {
    int sum = 0;
    int count = 0;
    int i = 1;
    while (arr[i] != 0) {   // ה-0 מסמן את סוף הסדרה
        int diff = arr[i - 1] - arr[i];
        if (diff > 0) {
            sum = sum + diff;
            count++;
        }
        i++;
    }
    if (count == 0) {
        return 0;
    }
    return (double) sum / count;
}

